insert into public.leyes (id,titulo,siglas,fecha_publicacion,fecha_ultima_reforma,vigente,temas_clave,url_original,tipo) values (E'71fd841c-97e4-5859-b39d-dbf8666a3fa0',E'Anexo III. Metadatos Descriptivos de la Norma Técnica para la elaboración de Metadatos de los Procesos de Producción de Información Estadística y Geográfica',E'METADATOS-III',null,null,true,ARRAY[E'SNIEG',E'INEGI',E'Información de Interés Nacional',E'Metadatos referenciales',E'Condición de llenado',E'DDI',E'SDMX']::text[],E'https://www.snieg.mx/Documentos/Normatividad/Vigente/anexos_III_ntmppieg.pdf',E'manual') on conflict(id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values (E'82bd810e-4587-5927-93bc-30caa4455885',E'Anexo III · 15 elementos descriptivos · pág. 1',E'<section><p>El presente anexo tiene por objeto listar cada uno de los elementos de la especificación de Metadatos Descriptivos para la representación estandarizada de los documentos técnicos y conceptuales que dan soporte a los Procesos de Producción, así como su respectiva condición de llenado. Esta especificación de metadatos fue adaptada a partir de la Iniciativa de Metadatos Dublín Core (DCMI) versión 1.1.</p><div class="overflow-x-auto"><table><thead><tr><th>Número</th><th>Sección</th><th>Apartado</th><th>Elemento</th><th>Condición de llenado</th></tr></thead><tbody><tr><td>1</td><td>Descripción de los materiales de soporte\nconceptual y metodológico</td><td>Identificación</td><td>Título del documento o material de referencia</td><td>Obligatorio</td></tr><tr><td>2</td><td>Descripción de los materiales de soporte\nconceptual y metodológico</td><td>Identificación</td><td>Fuente</td><td>Recomendado</td></tr><tr><td>3</td><td>Descripción de los materiales de soporte\nconceptual y metodológico</td><td>Identificación</td><td>Tipo</td><td>Obligatorio</td></tr><tr><td>4</td><td>Descripción de los materiales de soporte\nconceptual y metodológico</td><td>Identificación</td><td>Formato</td><td>Obligatorio</td></tr><tr><td>5</td><td>Descripción de los materiales de soporte\nconceptual y metodológico</td><td>Identificación</td><td>Identificador del documento o material de referencia</td><td>Recomendado</td></tr><tr><td>6</td><td>Descripción de los materiales de soporte\nconceptual y metodológico</td><td>Identificación</td><td>Fecha</td><td>Obligatorio</td></tr><tr><td>7</td><td>Descripción de los materiales de soporte\nconceptual y metodológico</td><td>Identificación</td><td>Idioma</td><td>Recomendado</td></tr><tr><td>8</td><td>Descripción de los materiales de soporte\nconceptual y metodológico</td><td>Propiedad intelectual</td><td>Autor</td><td>Obligatorio</td></tr><tr><td>9</td><td>Descripción de los materiales de soporte\nconceptual y metodológico</td><td>Propiedad intelectual</td><td>Editor</td><td>Recomendado</td></tr><tr><td>10</td><td>Descripción de los materiales de soporte\nconceptual y metodológico</td><td>Propiedad intelectual</td><td>Colaboradores</td><td>Recomendado</td></tr><tr><td>11</td><td>Descripción de los materiales de soporte\nconceptual y metodológico</td><td>Propiedad intelectual</td><td>Derechos</td><td>Recomendado</td></tr><tr><td>12</td><td>Descripción de los materiales de soporte\nconceptual y metodológico</td><td>Contenido</td><td>Descripción del contenido</td><td>Obligatorio</td></tr><tr><td>13</td><td>Descripción de los materiales de soporte\nconceptual y metodológico</td><td>Contenido</td><td>Temas</td><td>Obligatorio</td></tr><tr><td>14</td><td>Descripción de los materiales de soporte\nconceptual y metodológico</td><td>Contenido</td><td>Cobertura</td><td>Recomendado</td></tr><tr><td>15</td><td>Descripción de los materiales de soporte\nconceptual y metodológico</td><td>Contenido</td><td>Documentos relacionados</td><td>Recomendado</td></tr></tbody></table></div></section>',E'anexo',1,E'Anexo de la Norma Técnica de Metadatos',E'Metadatos descriptivos',E'Anexo III · 15 elementos descriptivos',E'71fd841c-97e4-5859-b39d-dbf8666a3fa0') on conflict(id) do nothing;
